export function expandPracticeAnswers(challenge) {
  const answers = challenge.answers.map(variants => [...variants]);
  const owners = new Map();
  for (const variants of answers) for (const alias of variants) owners.set(normalizeAnswer(alias), variants);
  for (const addition of practiceAnswerExpansions[challenge.id] ?? []) {
    const matches = new Set(addition.map(alias => owners.get(normalizeAnswer(alias))).filter(Boolean));
    if (matches.size > 1 && challenge.id !== 'programming-languages') throw new Error(`Conflicting answer expansion in ${challenge.id}: ${addition[0]}`);
    const variants = owners.get(normalizeAnswer(addition[0])) ?? (matches.size === 1 ? matches.values().next().value : []);
    if (!answers.includes(variants)) answers.push(variants);
    for (const alias of addition) {
      const key = normalizeAnswer(alias);
      if (owners.has(key) && owners.get(key) !== variants) continue;
      if (!owners.has(key)) variants.push(alias);
      owners.set(key, variants);
    }
  }
  return { ...challenge, answers };
}
